    let raw = (*input).raw as *mut crate::abi::structs::_xmlBuffer;
    let buf = (*input).buffer as *mut crate::abi::structs::_xmlBuffer;
    if raw.is_null() || buf.is_null() {
        return -1;
    }
    crate::xml::encoding::char_enc_in(handler, buf, raw)
}

