///
/// ```c
/// int xmlHasFeature(xmlFeature feature);
/// ```
#[no_mangle]
pub extern "C" fn xmlHasFeature(feature: c_int) -> c_int {
    // xmlFeature enum values (upstream xmlversion.h): XML_WITH_* run 1..24
