    sum += ret;
    let ret2 = unsafe { xmlTextWriterWriteString(writer, content) };
    if ret2 == -1 {
        return -1;
    }
    sum += ret2;
    let ret3 = unsafe { xmlTextWriterEndDTDAttlist(writer) };
    if ret3 == -1 {
