        if sysid.is_null() {
            // UPSTREAM-PARITY: PUBLIC requires a system identifier.
            return -1;
        }
        if w.indent != 0 {
            sum += w.write_byte(b'\n');
        } else {
            sum += w.write_byte(b' ');
