        if pubid.is_null() {
            sum += w.write_slice(b" SYSTEM");
        }
        sum += w.write_byte(b' ');
        sum += w.write_byte(w.qchar);
        sum += w.write_str(sysid);
        sum += w.write_byte(w.qchar);
