return xmlChar *(xmlTextWriterPtr, int, const xmlChar *, const xmlChar *, const xmlChar *, const xmlChar *)(fnptr) vs Rust Result<Vec<u8>, ()>(other); arg count 6 (xmlTextWriterPtr, int, const xmlChar *, const xmlChar *, const xmlChar *, const xmlChar *) vs Rust 11 (writer: *mut XmlTextWriter, pe: c_int, name: *const xmlChar, pubid: *const xmlChar, sysid: *const xmlChar, ndataid: *const xmlChar, ) -> c_int {
    if pubid.is_null() && sysid.is_null() {
        return -1;
