    if pubid.is_null() && sysid.is_null() {
        return -1;
    }
    if pe != 0 && !ndataid.is_null() {
        return -1;
    }
    let mut sum: c_int = 0;
    let ret = unsafe { xmlTextWriterStartDTDEntity(writer, pe, name) };
    if ret == -1 {
        return -1;
    }
    sum += ret;
    let ret2 =
        unsafe { xmlTextWriterWriteDTDExternalEntityContents(writer, pubid, sysid, ndataid) };
    if ret2 < 0 {
        return -1;
