/// Internal: leading/trailing helpers.
unsafe fn leading_nodes(nodes: &NodeSet, node: *mut _xmlNode) -> NodeSet {
    let mut out = NodeSet::new();
    for n in nodes.iter() {
        if n == node {
            break;
        }
        out.push(n);
    }
    out
}

unsafe fn trailing_nodes(nodes: &NodeSet, node: *mut _xmlNode) -> NodeSet {
    let mut out = NodeSet::new();
    let mut seen = false;
    for n in nodes.iter() {
        if n == node {
            seen = true;
            continue;
        }
        if seen {
            out.push(n);
        }
    }
    out
}

